What will be the output of the following C code snippet?
```c
int x = 5, y = 10;
if (x > 3 && y < 15)
    printf("YES");
else
    printf("NO");
```

What is the output of this loop?
```c
int sum = 0;
for (int i = 1; i <= 4; i++) {
    sum += i;
}
printf("%d", sum);
```

What will be printed by the following code?
```c
int a = 17 % 5;
printf("%d", a);
```

What will be the output of the following code?
```c
int count = 1;
while (count < 4) {
    count++;
}
printf("%d", count);
```

What is the value of `result` after execution?
```c
int a = 10, b = 3;
int result = a / b;
```

What does the following code print?
```c
int year = 2024;
if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))
    printf("LEAP");
else
    printf("NORMAL");
```

What is the exact output of this code snippet?
```c
int num = 8;
if (num % 2 == 0)
    printf("EVEN");
else
    printf("ODD");
```

What will be the output of this code?
```c
int x = 5;
int y = ++x;
printf("%d %d", x, y);
```

What will be the output of this code?
```c
int x = 5;
int y = x++;
printf("%d %d", x, y);
```

What is the output of the code below?
```c
int units = 120;
int bill = 0;
if (units <= 100) {
    bill = units * 2;
} else {
    bill = (100 * 2) + (units - 100) * 5;
}
printf("%d", bill);
```

What will be printed?
```c
int a = 3, b = 7;
if (a > 5 || b > 5)
    printf("MATCH");
else
    printf("NO MATCH");
```

What will happen during the execution of this code?
```c
int k = 1;
while (k <= 5) {
    printf("%d ", k);
}
```

What is the output of the following switch-case snippet?
```c
int ch = 2;
switch (ch) {
    case 1: printf("A"); break;
    case 2: printf("B");
    case 3: printf("C"); break;
    default: printf("D");
}
```

What will be printed by this code?
```c
int prod = 1;
for (int i = 1; i <= 3; i++) {
    prod *= i;
}
printf("%d", prod);
```

What is the output of the code?
```c
int x = 0;
if (x = 5)
    printf("TRUE");
else
    printf("FALSE");
```

What is the value of `val` printed?
```c
int val = (10 > 5) ? 100 : 200;
printf("%d", val);
```

What will be the output of this code?
```c
int i = 5;
while (i > 0) {
    i -= 2;
}
printf("%d", i);
```

What is the output of the following C code?
```c
int marks = 75;
if (marks >= 80)
    printf("A");
else if (marks >= 70)
    printf("B");
else
    printf("C");
```

What is printed by this loop?
```c
int count = 0;
for (int i = 0; i < 10; i += 3) {
    count++;
}
printf("%d", count);
```

What will be printed by the following code?
```c
int a = 15;
if (a % 3 == 0) {
    if (a % 5 == 0)
        printf("FIZZBUZZ");
    else
        printf("FIZZ");
}
```

What is the output of this code?
```c
int x = 4;
switch(x) {
    case 1: printf("One"); break;
    case 4: printf("Four"); break;
    default: printf("None");
}
```

What will be printed?
```c
int x = 20, y = 30;
int max = (x > y) ? x : y;
printf("%d", max);
```

What is the value of `i` after this loop finishes?
```c
int i;
for (i = 0; i < 5; i++) {
    // do nothing
}
```

What will be the output?
```c
int a = 5, b = 2;
float c = a / b;
printf("%.1f", c);
```

What will be printed?
```c
int sum = 0;
int i = 1;
do {
    sum += i;
    i++;
} while (i <= 3);
printf("%d", sum);
```

What will be printed by this code?
```c
int total = 0;
for (int i = 1; i <= 5; i++) {
    if (i % 2 != 0)
        total += i;
}
printf("%d", total);
```

What will be the output of this code?
```c
int x = 10;
if (x > 5)
    printf("A");
if (x > 8)
    printf("B");
```
